<?php get_header(); ?><section class="alify-section"><div class="container"><p class="alify-eyebrow"><?php esc_html_e('Search','alify'); ?></p><h1><?php printf(esc_html__('Search results for: %s','alify'),esc_html(get_search_query())); ?></h1><?php get_search_form(); ?><div class="row g-4"><?php if (have_posts()) : while (have_posts()) : the_post(); ?><div class="col-md-6"><article class="alify-card"><div class="alify-card-body"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(get_the_excerpt()); ?></p></div></article></div><?php endwhile; else : ?><p><?php esc_html_e('No results found.','alify'); ?></p><?php endif; ?></div><?php the_posts_pagination(); ?></div></section><?php get_footer(); ?>
